{
  "name": "是德科技 DSOX2024A 数字示波器",
  "name_en": "Keysight DSOX2024A Digital Oscilloscope",
  "manufacturer": "Keysight",
  "description": "一台台式数字示波器，用于观察、采集和测量电压信号随时间变化的波形。它支持多通道输入、触发控制、时基与垂直量程调节，以及自动测量功能，常用于电子电路调试、信号时域分析和实验室波形记录。",
  "description_en": "A benchtop digital oscilloscope used to view, acquire, and measure voltage waveforms over time. It supports multi-channel inputs, trigger control, timebase and vertical scaling adjustments, and automated measurements, making it suitable for electronics debugging, time-domain signal analysis, and laboratory waveform capture.",
  "tag_hints": [
    "digital oscilloscope",
    "waveform acquisition",
    "trigger configuration",
    "time-domain signal analysis",
    "multi-channel measurement",
    "bench test instrument"
  ],
  "actions": [
    {
      "action_name": "auto-reset",
      "description": "重置示波器。",
      "description_en": "Reset the oscilloscope."
    },
    {
      "action_name": "auto-clear_buffers",
      "description": "清除示波器缓冲区。",
      "description_en": "Clear the oscilloscope buffers."
    },
    {
      "action_name": "auto-autoscale",
      "description": "自动调整示波器量程与时基以适配输入信号。",
      "description_en": "Automatically adjust the oscilloscope scales and timebase to fit the input signal."
    },
    {
      "action_name": "auto-channel_info",
      "description": "获取通道信息。",
      "description_en": "Get channel information."
    },
    {
      "action_name": "auto-channel_coupling",
      "description": "获取或设置通道耦合方式。",
      "description_en": "Get or set the channel coupling mode."
    },
    {
      "action_name": "auto-channel_scale",
      "description": "获取或设置通道垂直量程。",
      "description_en": "Get or set the channel vertical scale."
    },
    {
      "action_name": "auto-channel_probe",
      "description": "获取或设置通道探头衰减倍数。",
      "description_en": "Get or set the channel probe attenuation."
    },
    {
      "action_name": "auto-channel_toggle",
      "description": "获取或设置通道启用状态。",
      "description_en": "Get or set whether the channel is enabled."
    },
    {
      "action_name": "auto-channel_invert",
      "description": "获取或设置通道波形是否反相。",
      "description_en": "Get or set whether the channel waveform is inverted."
    },
    {
      "action_name": "auto-channel_offset",
      "description": "获取或设置通道电压偏置。",
      "description_en": "Get or set the channel voltage offset."
    },
    {
      "action_name": "auto-channel_position",
      "description": "获取或设置通道垂直位置。",
      "description_en": "Get or set the channel vertical position."
    },
    {
      "action_name": "auto-trigger_channel",
      "description": "获取或设置触发源通道。",
      "description_en": "Get or set the trigger source channel."
    },
    {
      "action_name": "auto-trigger_slope",
      "description": "获取或设置触发沿方向。",
      "description_en": "Get or set the trigger slope."
    },
    {
      "action_name": "auto-trigger_level",
      "description": "获取或设置指定通道的触发电平。",
      "description_en": "Get or set the trigger level for the specified channel."
    },
    {
      "action_name": "auto-trigger_mode",
      "description": "获取或设置触发模式。",
      "description_en": "Get or set the trigger mode."
    },
    {
      "action_name": "auto-horizontal_offset",
      "description": "获取或设置水平时间偏移。",
      "description_en": "Get or set the horizontal time offset."
    },
    {
      "action_name": "auto-horizontal_scale",
      "description": "获取或设置水平时基量程。",
      "description_en": "Get or set the horizontal timebase scale."
    },
    {
      "action_name": "auto-trace",
      "description": "采集指定通道的波形轨迹数据。",
      "description_en": "Acquire waveform trace data from the specified channel."
    },
    {
      "action_name": "auto-measure_setup",
      "description": "定义测量槽位的测量项目和通道。",
      "description_en": "Define the measurement type and channel for a measurement slot."
    },
    {
      "action_name": "auto-measure",
      "description": "读取指定测量槽位的测量结果。",
      "description_en": "Read the measurement result from the specified measurement slot."
    }
  ]
}

